   280	PackLinuxElf32::PackLinuxElf32help1(InputFile *f)
   281	{
   282	    e_type  = get_te16(&ehdri.e_type);
   283	    e_phnum = get_te16(&ehdri.e_phnum);
   284	    e_shnum = get_te16(&ehdri.e_shnum);
   285	    unsigned const e_phentsize = get_te16(&ehdri.e_phentsize);
   286	    if (memcmp((char const *)&ehdri, "\x7f\x45\x4c\x46", 4)  // "\177ELF"
   287	    || ehdri.e_ident[Elf32_Ehdr::EI_CLASS]!=Elf32_Ehdr::ELFCLASS32
   288	    || sizeof(Elf32_Phdr) != e_phentsize
   289	    || (Elf32_Ehdr::ELFDATA2MSB == ehdri.e_ident[Elf32_Ehdr::EI_DATA]
   290	            && &N_BELE_RTP::be_policy != bele)
   291	    || (Elf32_Ehdr::ELFDATA2LSB == ehdri.e_ident[Elf32_Ehdr::EI_DATA]
   292	            && &N_BELE_RTP::le_policy != bele)) {
   293	        e_phoff = 0;
   294	        e_shoff = 0;
   295	        sz_phdrs = 0;
   296	        return;
   297	    }
   298	    if (0==e_phnum) throwCantUnpack("0==e_phnum");
   299	    e_phoff = get_te32(&ehdri.e_phoff);
   300	    unsigned const last_Phdr = e_phoff + e_phnum * usizeof(Elf32_Phdr);
   301	    if (last_Phdr < e_phoff  // wrap-around
   302	    ||  e_phoff != sizeof(Elf32_Ehdr)  // must be contiguous
   303	    ||  (unsigned long)file_size < last_Phdr) {
   304	        throwCantUnpack("bad e_phoff %#x", e_phoff);
   305	    }
   306	    e_shoff = get_te32(&ehdri.e_shoff);
   307	    e_shstrndx = get_te16(&ehdri.e_shstrndx);
   308	    unsigned const last_Shdr = e_shoff + e_shnum * usizeof(Elf32_Shdr);
   309	    if (last_Shdr < e_shoff  // wrap-around
   310	    ||  (e_shnum && e_shoff < last_Phdr)
   311	    ||  (unsigned long)file_size < last_Shdr) {
   312	        if (opt->cmd == CMD_COMPRESS) {
   313	            throwCantUnpack("bad e_shoff %#x", e_shoff);
   314	        }
   315	    }
   316	    sz_phdrs = e_phnum * e_phentsize;
   317	    sz_elf_hdrs = sz_phdrs + sizeof(Elf32_Ehdr) +
   318	        n_phdrx * sizeof(Elf32_Phdr);  // phdrx bodies later: ::generateElfHdr
   319	
   320	    if (f && Elf32_Ehdr::ET_DYN!=e_type) {
   321	        unsigned const len = file_size;  // (sz_phdrs + e_phoff) except --preserve-build-id
   322	        alloc_file_image(file_image, len);
   323	        f->seek(0, SEEK_SET);
   324	        f->readx(file_image, len);
   325	        phdri= (Elf32_Phdr       *)(e_phoff + file_image);  // do not free() !!
   326	    }
   327	    if (f && Elf32_Ehdr::ET_DYN==e_type) {
   328	        // The DT_SYMTAB has no designated length.  Read the whole file.
   329	        alloc_file_image(file_image, file_size);
   330	        f->seek(0, SEEK_SET);
   331	        f->readx(file_image, file_size);
   332	        phdri= (Elf32_Phdr *)(e_phoff + file_image);  // do not free() !!
   333	        if (opt->cmd != CMD_COMPRESS || !e_shoff ||  file_size < e_shoff) {
   334	            shdri = nullptr;
   335	        }
   336	        else {  // FIXME: copy from file_image ?
   337	            fi->seek(e_shoff, SEEK_SET);
   338	            if (mb_shdr.getSize() != sizeof(Elf32_Shdr) * e_shnum) {
   339	                mb_shdr.alloc(   sizeof(Elf32_Shdr) * e_shnum);
   340	            }
   341	            shdri = (Elf32_Shdr *)mb_shdr.getVoidPtr();
   342	            fi->readx(shdri, sizeof(Elf32_Shdr) * e_shnum);
   343	        }
   344	        sec_dynsym = elf_find_section_type(Elf32_Shdr::SHT_DYNSYM);
   345	        if (sec_dynsym) {
   346	            unsigned t = get_te32(&sec_dynsym->sh_link);
   347	            if (e_shnum <= t)
   348	                throwCantPack("bad dynsym->sh_link");
   349	            sec_dynstr = &shdri[t];
   350	        }
   351	
   352	        Elf32_Phdr const *phdr= phdri;
   353	        for (int j = e_phnum; --j>=0; ++phdr)
   354	        if (Elf32_Phdr::PT_DYNAMIC==get_te32(&phdr->p_type)) {
   355	            unsigned offset = check_pt_dynamic(phdr);
   356	            dynseg= (Elf32_Dyn *)(offset + file_image);
   357	            invert_pt_dynamic(dynseg,
   358	                umin(get_te32(&phdr->p_filesz), (unsigned)(file_size_u - offset)));
   359	        }
   360	        else if (is_LOAD(phdr)) {
   361	            check_pt_load(phdr);
   362	        }
   363	        // elf_find_dynamic() returns 0 if 0==dynseg.
   364	        dynstr =          (char const *)elf_find_dynamic(Elf32_Dyn::DT_STRTAB);
   365	        dynsym = (Elf32_Sym /*const*/ *)elf_find_dynamic(Elf32_Dyn::DT_SYMTAB);
   366	        gashtab =     (unsigned const *)elf_find_dynamic(Elf32_Dyn::DT_GNU_HASH);
   367	        hashtab =     (unsigned const *)elf_find_dynamic(Elf32_Dyn::DT_HASH);
   368	        if (3& ((upx_uintptr_t)dynsym | (upx_uintptr_t)gashtab | (upx_uintptr_t)hashtab)) {
   369	            throwCantPack("unaligned DT_SYMTAB, DT_GNU_HASH, or DT_HASH/n");
   370	        }
   371	        jni_onload_sym = elf_lookup("JNI_OnLoad");
   372	        if (jni_onload_sym) {
   373	            jni_onload_va = get_te32(&jni_onload_sym->st_value);
   374	            jni_onload_va = 0;  // FIXME not understood; need example
   375	        }
   376	    }
